input.content:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses the book catalogue and places orders."
        bookshop = softwareSystem "Bookshop" "An online bookshop where customers browse books and place orders." {
            webStore = container "Web Store" "The web application customers use to browse the catalogue and place orders." "Java / Spring Boot"
            orderProcessor = container "Order Processor" "Processes orders placed through the Web Store and prepares them for fulfilment." "Java / Spring Batch"
        }

        customer -> webStore "Browses the catalogue and places orders through" "HTTPS/HTML"
        webStore -> orderProcessor "Submits new orders to" "REST/JSON"
    }

    views {
        systemContext bookshop "systemContext" "Shows the Customer and the Bookshop system." {
            include *
            autoLayout
        }
    }
}

